    "id": "log-201-glossaire-reconstitue",
    "kind": "glossaire",
    "blocks": [
      {
        "kind": "paragraph",
        "text": "{g}acheteur{/g} — Personne ou organisation qui passe l’achat, pour elle-même ou pour le compte d’un client."
      },
      {
        "kind": "paragraph",
        "text": "{g}chiffre d’affaires{/g} — Montant des ventes réalisées sur une période selon les règles comptables applicables."
      },
      {
        "kind": "paragraph",
        "text": "{g}client{/g} — Personne ou organisation qui achète un bien ou une prestation."
      },
      {
        "kind": "paragraph",
        "text": "{g}client fidèle{/g} — Client qui revient régulièrement chez un même fournisseur."
      },
      {
        "kind": "paragraph",
        "text": "{g}client interne{/g} — Personne ou service de la même organisation qui reçoit une prestation, un produit ou une information."
      },
      {
        "kind": "paragraph",
        "text": "{g}client professionnel{/g} — Organisation ou personne agissant dans le cadre de son activité professionnelle."
      },
      {
        "kind": "paragraph",
        "text": "{g}créance{/g} — Droit de demander le paiement d’un montant dû."
      },
      {
        "kind": "paragraph",
        "text": "{g}débiteur{/g} — Personne ou organisation qui doit une somme à une autre."
      },
      {
        "kind": "paragraph",
        "text": "{g}destinataire{/g} — Personne ou organisation à laquelle un envoi est remis."
      },
      {
        "kind": "paragraph",
        "text": "{g}encaissement{/g} — Réception effective d’un paiement."
      },
      {
        "kind": "paragraph",
        "text": "{g}facture{/g} — Document indiquant les biens ou prestations facturés, leurs montants et les modalités de paiement."
      },
      {
        "kind": "paragraph",
        "text": "{g}offre{/g} — Proposition qui précise le produit ou la prestation, le prix et les conditions."
      },
      {
        "kind": "paragraph",
        "text": "{g}réclamation{/g} — Signalement d’un écart par un client qui demande une vérification ou une solution."
      },
      {
        "kind": "paragraph",
        "text": "{g}service client{/g} — Équipe ou activité qui répond aux demandes, suit les dossiers et traite les écarts."
      }
    ],
